from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from django.shortcuts import get_object_or_404
from tenant_users.permissions.models import UserTenantPermissions

class UpdateTenantUserRoleView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def patch(self, request, permission_id):
        tenant_perm = get_object_or_404(UserTenantPermissions, id=permission_id)
        # Verify that request.user is an owner of the target tenant
        if not UserTenantPermissions.objects.filter(tenant=tenant_perm.tenant, profile=request.user, is_owner=True).exists():
            return Response({'error': 'Access denied: You are not an owner of this tenant'}, status=status.HTTP_403_FORBIDDEN)

        new_role = request.data.get('role')
        if not new_role:
            return Response({'error': 'role required'}, status=status.HTTP_400_BAD_REQUEST)

        tenant_perm.role = new_role
        tenant_perm.save(update_fields=['role'])
        return Response({'id': tenant_perm.id, 'role': tenant_perm.role})
